from datetime import datetime, timedelta

def parse(path):
    evs, cur = [], None
    for line in open(path):
        line = line.strip()
        if line == 'BEGIN:VEVENT':
            cur = {}
        elif line == 'END:VEVENT':
            if cur is not None:
                evs.append((cur['DTSTART'], cur['DTEND']))
            cur = None
        elif cur is not None and ':' in line:
            k, v = line.split(':', 1)
            if k in ('DTSTART', 'DTEND'):
                cur[k] = datetime.strptime(v, '%Y%m%dT%H%M%SZ')
    return evs

alice = parse('/app/alice_calendar.ics')
bob = parse('/app/bob_calendar.ics')
carol = parse('/app/carol_calendar.ics')

BUS_START, BUS_END = 9, 18
DAYS = [datetime(2024, 1, 15) + timedelta(days=i) for i in range(5)]  # Mon..Fri

def busy(busy_list, s, e):
    for bs, be in busy_list:
        if s < be and bs < e:
            return True
    return False

def alice_ok(s, e):
    # hard: within 9:00-14:00
    if s.hour < 9 or (e > s.replace(hour=14, minute=0)):
        return False
    if e.time() > datetime(2024,1,1,14,0).time():
        return False
    return not busy(alice, s, e)

def bob_ok(s, e):
    # hard: no earlier than 10:00; on Tue/Thu must end by 16:30
    if s.time() < datetime(2024,1,1,10,0).time():
        return False
    if s.weekday() in (1, 3) and e.time() > datetime(2024,1,1,16,30).time():
        return False
    return not busy(bob, s, e)

def carol_ok(s, e):
    # hard: 9:00-17:00, lunch 12:00-12:30 blocked
    if s.time() < datetime(2024,1,1,9,0).time():
        return False
    if e.time() > datetime(2024,1,1,17,0).time():
        return False
    if s < s.replace(hour=12, minute=30) and s.replace(hour=12, minute=0) < e:
        return False  # overlaps lunch window 12:00-12:30
    if busy(carol, s, e):
        return False
    # buffer: 15 min after any of her meetings ending >= 16:45
    for bs, be in carol:
        if be.time() >= datetime(2024,1,1,16,45).time():
            if s < be + timedelta(minutes=15) and bs < e:
                return False
    return True

valid = []
for d in DAYS:
    t = d.replace(hour=BUS_START, minute=0)
    end_of_day = d.replace(hour=BUS_END, minute=0)
    while t + timedelta(minutes=60) <= end_of_day:
        s, e = t, t + timedelta(minutes=60)
        if alice_ok(s, e) and bob_ok(s, e) and carol_ok(s, e):
            valid.append((s, e))
        t += timedelta(minutes=1)

print("total valid 1h slots:", len(valid))
for s, e in valid[:10]:
    print("  ", s.strftime('%a %Y%m%dT%H%M'), "-", e.strftime('%H%M'))

if valid:
    s, e = valid[0]
    print("EARLIEST:", s.strftime('%Y%m%dT%H%M%SZ'), e.strftime('%Y%m%dT%H%M%SZ'))
    ics = f"""BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//Terminal-Bench//Meeting Scheduler//EN
CALSCALE:GREGORIAN
METHOD:PUBLISH
BEGIN:VEVENT
UID:team-planning-meeting-20240117@example.com
DTSTAMP:{datetime.utcnow().strftime('%Y%m%dT%H%M%SZ')}
DTSTART:{s.strftime('%Y%m%dT%H%M%SZ')}
DTEND:{e.strftime('%Y%m%dT%H%M%SZ')}
SUMMARY:Team Planning Meeting
DESCRIPTION:1-hour team planning meeting for Alice\\, Bob\\, and Carol
LOCATION:Conference Room A
ORGANIZER:mailto:alice@example.com
ATTENDEE;CN=Alice;ROLE=REQ-PARTICIPANT;PARTSTAT=ACCEPTED:mailto:alice@example.com
ATTENDEE;CN=Bob;ROLE=REQ-PARTICIPANT;PARTSTAT=ACCEPTED:mailto:bob@example.com
ATTENDEE;CN=Carol;ROLE=REQ-PARTICIPANT;PARTSTAT=ACCEPTED:mailto:carol@example.com
STATUS:CONFIRMED
END:VEVENT
END:VCALENDAR
"""
    open('/app/meeting_scheduled.ics', 'w').write(ics)
    print("--- written /app/meeting_scheduled.ics ---")
    print(ics)
EOF
