from datetime import datetime, timedelta

def parse(path):
    evs, cur = [], None
    for line in open(path):
        line = line.rstrip('\n').strip()
        if line == 'BEGIN:VEVENT':
            cur = {}
        elif line == 'END:VEVENT':
            evs.append((cur['DTSTART'], cur['DTEND'])); cur = None
        elif cur is not None and line.startswith(('DTSTART', 'DTEND')):
            k, v = line.split(':', 1)
            cur[k] = datetime.strptime(v, '%Y%m%dT%H%M%SZ')
    return evs

alice, bob, carol = [parse(f'/app/{n}_calendar.ics') for n in ('alice','bob','carol')]
out = parse('/app/meeting_scheduled.ics')
print('VEVENTs in output:', len(out))
s, e = out[0]
print('Slot:', s, '->', e, '| duration:', e - s)

def busy(lst, a, b): return any(a < be and bs < b for bs, be in lst)

errs = []
if e - s != timedelta(hours=1): errs.append('duration != 1h')
if s.weekday() > 4: errs.append('weekend')
if s.time() < datetime(2024,1,1,9,0).time() or e.time() > datetime(2024,1,1,18,0).time():
    errs.append('outside business hours')

# Alice: 9:00-14:00 hard bound
if s.time() < datetime(2024,1,1,9,0).time() or e > s.replace(hour=14, minute=0, second=0):
    errs.append('violates Alice 9AM-2PM bound')
if busy(alice, s, e): errs.append('conflicts with Alice calendar')

# Bob: not before 10:00; Tue/Thu end by 16:30
if s.time() < datetime(2024,1,1,10,0).time(): errs.append('violates Bob 10AM start')
if s.weekday() in (1,3) and e.time() > datetime(2024,1,1,16,30).time():
    errs.append('violates Bob Tue/Thu 4:30PM leave')
if busy(bob, s, e): errs.append('conflicts with Bob calendar')

# Carol: 9:00-17:00, lunch 12:00-12:30, 15min buffer after meetings ending >=16:45
if s.time() < datetime(2024,1,1,9,0).time() or e.time() > datetime(2024,1,1,17,0).time():
    errs.append('violates Carol 9-5')
if s < s.replace(hour=12,minute=30) and s.replace(hour=12,minute=0) < e:
    errs.append('overlaps Carol lunch 12:00-12:30')
if busy(carol, s, e): errs.append('conflicts with Carol calendar')
for bs, be in carol:
    if be.time() >= datetime(2024,1,1,16,45).time() and s < be + timedelta(minutes=15) and bs < e:
        errs.append('violates Carol buffer')

# Earliest check: full minute-granularity rescan
def ok(a, b):
    if a.time() < datetime(2024,1,1,9,0).time() or b.time() > datetime(2024,1,1,18,0).time(): return False
    if b > a.replace(hour=14,minute=0,second=0): return False
    if a.time() < datetime(2024,1,1,10,0).time(): return False
    if a.weekday() in (1,3) and b.time() > datetime(2024,1,1,16,30).time(): return False
    if b.time() > datetime(2024,1,1,17,0).time(): return False
    if a < a.replace(hour=12,minute=30) and a.replace(hour=12,minute=0) < b: return False
    if busy(alice,a,b) or busy(bob,a,b) or busy(carol,a,b): return False
    for bs, be in carol:
        if be.time() >= datetime(2024,1,1,16,45).time() and a < be+timedelta(minutes=15) and bs < b: return False
    return True

earliest = None
for d in range(5):
    day = datetime(2024,1,15)+timedelta(days=d)
    t = day.replace(hour=9)
    while t + timedelta(hours=1) <= day.replace(hour=18):
        if ok(t, t+timedelta(hours=1)):
            earliest = (t, t+timedelta(hours=1)); break
        t += timedelta(minutes=1)
    if earliest: break
print('Earliest valid slot by rescan:', earliest)
if earliest != (s, e): errs.append(f'slot is not the earliest ({earliest})')
print('Carol Monday?', s.weekday()==0, '| Alice morning?', e.hour <= 12)
print('RESULT:', 'PASS' if not errs else 'FAIL ' + '; '.join(errs))
EOF
